class Snake:
    def __init__(self, canvas, difficulty):
        self.canvas = canvas
        self.size = 10
        self.direction = random.choice(['Up', 'Down', 'Left', 'Right'])
        self.body = deque(self.initialPosition())
        self.difficulty = difficulty
        self.draw()

    def initialPosition(self):
        while True:
            initial_x = random.randint(5, self.canvas.winfo_width()//self.size - 5) * self.size
            initial_y = random.randint(5, self.canvas.winfo_height()//self.size - 5) * self.size
            pos = [(initial_x, initial_y, initial_x + self.size, initial_y + self.size),
                   (initial_x - self.size, initial_y, initial_x, initial_y + self.size),
                   (initial_x - 2 * self.size, initial_y, initial_x - self.size, initial_y + self.size)]
            if not self.checkCollision(pos):
                return pos

    def checkCollision(self, positions):
        for x1, y1, x2, y2 in positions:
            if x1 < 0 or x2 > self.canvas.winfo_width() or y1 < 0 or y2 > self.canvas.winfo_height() or (x1, y1, x2, y2) in list(self.body)[1:]:
                return True
        return False

    def move(self):
        self.advance(self.direction)
        if self.checkCollision([self.body[0]]):
            return True
        else:
            self.canvas.delete(self.canvas.find_withtag("snake")[-1])
            self.body.pop()
            self.draw()
            return False

    def grow(self):
        self.advance(self.direction)
        self.draw()

    def advance(self, direction):
        head = self.body[0]
        x1, y1, x2, y2 = head
        directions = {
            'Up': (x1, y1 - self.size, x2, y2 - self.size),
            'Down': (x1, y1 + self.size, x2, y2 + self.size),
            'Left': (x1 - self.size, y1, x2 - self.size, y2),
            'Right': (x1 + self.size, y1, x2 + self.size, y2)
        }
        newHead = directions[direction]
        self.body.appendleft(newHead)

    def changeDirection(self, newDirection):
        opposites = {'Up': 'Down', 'Down': 'Up', 'Left': 'Right', 'Right': 'Left'}
        if newDirection != opposites[self.direction]:
            self.direction = newDirection

    def draw(self):
        self.canvas.create_rectangle(self.body[0], fill='white', tag='snake')
